"""Report content, part C: Question 5."""
import math

from content_a import load, g, e, f


def section5(R):
    B = []
    ref = R["reference"]
    tab = R["q5_1_table"]
    B.append(("h1", "Question 5 - Denoising and the Wiener filter"))
    B.append(("h2", "5.1 The Wiener filter as an MMSE denoiser"))
    B.append(("p", "**Derivation.** Let $g=f+n$ with $f$ and $n$ uncorrelated, zero-mean, wide-sense stationary random fields with power spectral densities $S_{ff}$, $S_{nn}$. Stationarity makes the DFT diagonalise the covariance, so the best *linear* (shift-invariant) estimate is a per-frequency gain, $\\hat F(u,v)=W(u,v)G(u,v)$, chosen to minimise $J(W)=E|F-WG|^2$ at each frequency. With $E|F|^2=S_{ff}$, $E|G|^2=S_{ff}+S_{nn}$ and $E[F\\bar G]=S_{ff}$ (uncorrelated noise), for the real gain $W$ of a symmetric estimator"))
    B.append(("eq", r"J(W)=S_{ff}-2W S_{ff}+W^{2}(S_{ff}+S_{nn}),\qquad \frac{dJ}{dW}=0\ \Rightarrow\ W=\frac{S_{ff}}{S_{ff}+S_{nn}},\quad J_{\min}=\frac{S_{ff}S_{nn}}{S_{ff}+S_{nn}}"))
    B.append(("p", "(the second derivative $2(S_{ff}+S_{nn})>0$ confirms a minimum). The estimate is $\\hat F=\\frac{S_{ff}}{S_{ff}+S_{nn}}G=\\frac{\\mathrm{SNR}}{\\mathrm{SNR}+1}G$ with $\\mathrm{SNR}(u,v)=S_{ff}/S_{nn}$: the gain is $\\approx1$ where the signal dominates and $\\approx\\mathrm{SNR}\\ll1$ where noise dominates, and the residual error $J_{\\min}\\le\\min(S_{ff},S_{nn})$ is never worse than doing nothing or keeping nothing."))
    B.append(("p", "**Implementation (src/q5_wiener.py).** Working image: the instructor-provided `reference_image.jpg` is %dx%d (native, RGB); to keep the 2-D FFTs and the from-scratch bilateral filter tractable it is reduced by 2x2 block averaging to **%dx%d** (both sides >= 1024 as the assignment requires; the reduction is area averaging, stored as `data/derived/reference_work_1536x1024.png`). Intensities are normalised to [0,1] inside the Wiener filter; noise is white Gaussian with $\\sigma\\in\\{5,10,20,40\\}$ 8-bit levels, generated as $\\sigma z$ from **one** unit-variance realisation $z$ (seed 2026), so every method sees the same noise at each $\\sigma$; the noisy image is **not** clipped before filtering (clipping only for display and for the metrics). Each colour channel is processed independently. The channel is mirror-padded by 64 px (to a fast FFT size) to avoid wrap-around; $S_{nn}=\\sigma^2$ exactly (periodogram normalisation $|G|^2/(P_rP_c)$, white noise has flat periodogram $\\sigma^2$); the signal PSD is estimated from the noisy image itself: radially averaged periodogram (240 log-spaced radial bins, interpolated back to 2-D) minus $S_{nn}$, floored at $0.01\\,S_{nn}$ so that $W\\ge0.0099$ at the highest frequencies. **Assumptions:** (i) noise white, stationary, signal-independent and Gaussian; (ii) $f$ stationary with an *isotropic* spectrum (the radial average discards the horizontal/vertical dominance of real photographs); (iii) the periodogram is a consistent estimate after radial averaging; (iv) the noise power is either known (injected $\\sigma$) or estimated blindly with Immerkaer's method (Table 5.1 reports both: $\\hat\\sigma$ = %s for $\\sigma=5,10,20,40$)." % (ref["native_shape_HxWxC"][1], ref["native_shape_HxWxC"][0], ref["working_shape_HxWxC"][1], ref["working_shape_HxWxC"][0], ", ".join(f(d["wiener_estimated_sigma"]["sigma_hat"], 2) for d in tab))))
    B.append(("p", "**Competitors.** (a) Problem 2 low-pass filters: Butterworth ($n=2$) and Gaussian (matched $D_0'=D_0/\\sqrt{2\\ln2}$), same formulas as `make_filter` but with mirror padding and cutoffs in cycles/pixel; the cutoff $f_c$ is chosen from 28 log-spaced values in $[0.01,0.5]$ by maximum PSNR on a 512x512 centre crop against the clean image - **oracle-tuned**. A *blind* Gaussian cutoff (the radius at which the estimated $S_{ff}$ falls below $S_{nn}$) is also reported. (b) Problem 4 bilateral filter (applied per channel), $\\sigma_s\\in\\{1,2,3\\}$, $\\sigma_r\\in\\{1,2,3\\}\\sigma$ tuned on the same crop with the clean reference - **oracle-tuned**. The Wiener results use no clean-reference information (known $\\sigma$ or estimated $\\hat\\sigma$)."))
    rows = []
    for d in tab:
        s = d["sigma"]
        rows.append([s, "noisy input", f(d["noisy"]["PSNR"], 2), f(d["noisy"]["SSIM"], 4), "-"])
        rows.append(["", "Wiener (known sigma)", f(d["wiener_known_sigma"]["PSNR"], 2), f(d["wiener_known_sigma"]["SSIM"], 4), "S_nn = sigma^2; blind w.r.t. the clean image"])
        rows.append(["", "Wiener (Immerkaer sigma-hat = %.2f)" % d["wiener_estimated_sigma"]["sigma_hat"], f(d["wiener_estimated_sigma"]["PSNR"], 2), f(d["wiener_estimated_sigma"]["SSIM"], 4), "fully blind"])
        rows.append(["", "Butterworth n=2 (oracle-tuned)", f(d["BLPF_n2_oracle"]["PSNR"], 2), f(d["BLPF_n2_oracle"]["SSIM"], 4), "f_c = %.3f cyc/px%s" % (d["BLPF_n2_oracle"]["fc_cycles_per_pixel"], " (grid edge)" if d["BLPF_n2_oracle"]["fc_cycles_per_pixel"] >= 0.499 else "")])
        rows.append(["", "Gaussian matched (oracle-tuned)", f(d["GLPF_oracle"]["PSNR"], 2), f(d["GLPF_oracle"]["SSIM"], 4), "f_c(half-amplitude) = %.3f cyc/px%s" % (d["GLPF_oracle"]["fc_cycles_per_pixel"], " (grid edge)" if d["GLPF_oracle"]["fc_cycles_per_pixel"] >= 0.499 else "")])
        rows.append(["", "Gaussian, blind cutoff (S_ff = S_nn)", f(d["GLPF_blind_Sff=Snn_crossing"]["PSNR"], 2), f(d["GLPF_blind_Sff=Snn_crossing"]["SSIM"], 4), "f_c = %.3f cyc/px" % d["GLPF_blind_Sff=Snn_crossing"]["fc_cycles_per_pixel"]])
        rows.append(["", "Bilateral (oracle-tuned)", f(d["bilateral_oracle"]["PSNR"], 2), f(d["bilateral_oracle"]["SSIM"], 4), "sigma_s = %g, sigma_r = %g sigma" % (d["bilateral_oracle"]["sigma_s"], d["bilateral_oracle"]["sigma_r_over_sigma"])])
    B.append(("table", "Table 5.1. PSNR (dB, data range 255) and SSIM (own implementation, Gaussian 11x11, sigma 1.5, mean over RGB) on the 1536x1024 working image, same noise realisation for all methods at each sigma. Oracle-tuned = parameters chosen with the clean reference on a 512x512 centre crop; the metrics are on the full image.", ["sigma", "method", "PSNR", "SSIM", "parameters / remark"], rows, "rlrrl"))
    B.append(("fig", "figures/q5_comparison_crops.png", "Crops (200x300 px) at sigma = 20 (top) and 40 (bottom): clean, noisy, Wiener, Gaussian (oracle), Butterworth (oracle), bilateral (oracle).", 1.0))
    B.append(("fig", "figures/q5_wiener_gain.png", "Left: Wiener gain W(f) along the horizontal frequency axis for each sigma (green channel) and two fixed low-pass filters (dashed, f_c = 0.1). Middle: radial periodogram of the noisy image with the white level sigma^2 (dotted). Right: 2-D Wiener gain at sigma = 20.", 1.0))
    w5, w10, w20, w40 = [d["wiener_known_sigma"] for d in tab]
    b5, b10, b20, b40 = [d["bilateral_oracle"] for d in tab]
    B.append(("p", "**How the shrinkage changes with frequency and noise power.** $W(f)=1/(1+1/\\mathrm{SNR}(f))$: close to 1 at low frequency where the periodogram is orders of magnitude above $\\sigma^2$, then decreasing monotonically through $W=1/2$ at the frequency where $S_{ff}=S_{nn}$ and approaching $S_{ff}/S_{nn}$ beyond (Figure 5.2). When $\\sigma$ grows the white level $\\sigma^2$ moves up, the crossing moves to lower frequency: the blind crossing radii are %s cycles/pixel for $\\sigma=5,10,20,40$, i.e. the Wiener filter automatically tightens its bandwidth by a factor of about %.1f over this range. **Difference from a fixed-cutoff low-pass:** a fixed filter has a prescribed shape (flat passband, one transition width, a single cutoff chosen by the user, ideal: 0/1) that does not depend on the data; the Wiener gain follows the *estimated image spectrum*: it has no sharp cutoff, it attenuates gradually exactly where the SNR degrades, and it keeps components above the 'cutoff' if they are strong (e.g. along the dominant horizontal/vertical edge directions in the 2-D gain of Figure 5.2 right, if an anisotropic $S_{ff}$ estimate were used; the radial average used here makes the gain isotropic). If $S_{ff}$ were a step in frequency the Wiener filter would reduce to an ideal low-pass." % (", ".join(f(d["GLPF_blind_Sff=Snn_crossing"]["fc_cycles_per_pixel"], 3) for d in tab), tab[0]["GLPF_blind_Sff=Snn_crossing"]["fc_cycles_per_pixel"] / tab[3]["GLPF_blind_Sff=Snn_crossing"]["fc_cycles_per_pixel"])))
    B.append(("p", "**Results and what they do (not) show.** Without access to the clean image the Wiener filter gains %.2f, %.2f, %.2f, %.2f dB over the noisy input for $\\sigma=5,10,20,40$ and is within 0.3 dB of the *oracle-tuned* Butterworth/Gaussian low-pass filters at every noise level (+%.2f, +%.2f, +%.2f, +%.2f dB over the oracle Butterworth); at $\\sigma=5$ the oracle cutoff is at the edge of the search grid (0.5 cycles/pixel), so this one comparison is not a clean optimum. The blind Gaussian cutoff from the $S_{ff}=S_{nn}$ crossing gets within 0.2 dB of the Wiener result at all $\\sigma$, which shows that for a *linear, isotropic* filter most of the benefit comes from locating the right bandwidth. The **bilateral filter wins on PSNR and SSIM at $\\sigma=5,10$** (%.2f vs %.2f dB and %.2f vs %.2f dB, SSIM 0.939/0.868 vs 0.919/0.839) and on PSNR at $\\sigma=20$ (%.2f vs %.2f dB, with *lower* SSIM, %.3f vs %.3f); only at the highest noise level $\\sigma=40$ does Wiener beat it in PSNR (%.2f vs %.2f dB) and SSIM (%.3f vs %.3f). The comparison is moreover tilted towards the bilateral filter: its two parameters were oracle-tuned with the clean image while the Wiener filter used none. So **Wiener does not win every comparison**, consistent with the theory: its optimality is for *linear* estimators under stationary second-order statistics, whereas the bilateral filter is nonlinear, adapts locally to edges (images are not stationary), and can exceed the linear MMSE bound on PSNR; where noise is so strong that the range term can no longer separate edges from noise ($\\sigma=40$ is $\\mathrm{NCR}=0.4$ for an edge of contrast 100 grey levels and larger for weaker edges, cf. Section 4.3) the advantage disappears." % (w5["PSNR"] - tab[0]["noisy"]["PSNR"], w10["PSNR"] - tab[1]["noisy"]["PSNR"], w20["PSNR"] - tab[2]["noisy"]["PSNR"], w40["PSNR"] - tab[3]["noisy"]["PSNR"],
                                                                  w5["PSNR"] - tab[0]["BLPF_n2_oracle"]["PSNR"], w10["PSNR"] - tab[1]["BLPF_n2_oracle"]["PSNR"], w20["PSNR"] - tab[2]["BLPF_n2_oracle"]["PSNR"], w40["PSNR"] - tab[3]["BLPF_n2_oracle"]["PSNR"],
                                                                  b5["PSNR"], w5["PSNR"], b10["PSNR"], w10["PSNR"], b20["PSNR"], w20["PSNR"], b20["SSIM"], w20["SSIM"], w40["PSNR"], b40["PSNR"], w40["SSIM"], b40["SSIM"])))

    # ---- 5.2
    B.append(("h2", "5.2a Noise-power mis-specification and edge blur"))
    mis = R["q5_2_misestimation"]
    B.append(("p", "**Wrong noise power.** At $\\sigma=20$ the Wiener filter was re-run assuming noise power $\\kappa S_{nn}$ with $\\kappa\\in\\{0.5,1,2\\}$: $W_\\kappa=\\frac{S_{ff}}{S_{ff}+\\kappa S_{nn}}$. Two variants are reported: (A) the signal PSD estimate is unchanged (it was obtained with the correct $S_{nn}$) and only the denominator is mis-specified - this isolates the formula; (B) the signal PSD is re-estimated by subtracting the *assumed* noise power, $S_{ff}^{(\\kappa)}=\\bar P-\\kappa S_{nn}$, which is what a user who believes the wrong $\\sigma$ would actually do, giving $W=1-\\kappa S_{nn}/\\bar P$. Residual noise is measured as the standard deviation of (output - clean) in the flattest 48x48 clean-image block (the noisy input has %.1f there) and edge preservation as the mean gradient magnitude of the output over the strongest 5%% clean-gradient pixels relative to the clean image."  % mis["noisy_flat_patch_std"]))
    rows = []
    for r in mis["rows"]:
        rows.append(["A (S_ff fixed)" if r["variant"].startswith("signal_PSD_from") else "B (S_ff refit)", r["assumed_noise_power_factor"], f(r["PSNR"], 2), f(r["SSIM"], 4), f(r["flat_patch_residual_std_(vs_clean)"], 2), f(r["edge_gradient_retention"], 3)])
    B.append(("table", "Table 5.2. Noise-power mis-specification at sigma = 20 (1536x1024 reference). The 1.0 rows are the correctly specified filter (identical in both variants).", ["variant", "assumed noise power / true", "PSNR", "SSIM", "residual noise std in flat patch", "edge gradient retention"], rows, "lrrrrr"))
    B.append(("fig", "figures/q5_misestimation.png", "Noise-power mis-estimation at sigma = 20 (crop): noisy, 0.5 S_nn, correct S_nn, 2 S_nn, clean.", 1.0))
    A = {r["assumed_noise_power_factor"]: r for r in mis["rows"] if r["variant"].startswith("signal_PSD_from")}
    Bv = {r["assumed_noise_power_factor"]: r for r in mis["rows"] if not r["variant"].startswith("signal_PSD_from")}
    B.append(("p", "**Explanation.** With $0.5S_{nn}$ the gain $W_{0.5}=S_{ff}/(S_{ff}+0.5S_{nn})$ is larger than the correct one at every frequency, most where $S_{ff}\\approx S_{nn}$ (the transition band), so more noise passes: the flat-patch residual noise rises from %s to %s grey levels and the picture looks grainy, while edges are better preserved (gradient retention %s vs %s); the PSNR drops by %.2f dB. With $2S_{nn}$ the gain is smaller (cutoff moves to lower frequency): residual noise falls to %s but signal is removed as well - smoother, more blurred (edge retention %s) - and PSNR drops by %.2f dB. SSIM *increases* from %s to %s at $2S_{nn}$ because SSIM penalises residual noise in flat regions (which dominate the image) more than blur of the sparse edges, a case where the two metrics disagree. The penalty is asymmetric: the MSE-optimal setting is the correct one (PSNR %s dB) and the loss is small (<0.4 dB) for a factor-of-two error in either direction since $J(W)$ is flat near its minimum, but it is larger when the noise power is under-estimated *and* the signal PSD is re-fitted with the same wrong value (variant B: %.2f dB at $0.5\\times$ and %.2f dB at $2\\times$), because then both $S_{ff}$ and $S_{nn}$ are biased." % (f(mis["noisy_flat_patch_std"], 1) if False else f(mis["rows"][1]["flat_patch_residual_std_(vs_clean)"], 2), f(A[0.5]["flat_patch_residual_std_(vs_clean)"], 2), f(A[0.5]["edge_gradient_retention"], 3), f(A[1.0]["edge_gradient_retention"], 3), A[1.0]["PSNR"] - A[0.5]["PSNR"], f(A[2.0]["flat_patch_residual_std_(vs_clean)"], 2), f(A[2.0]["edge_gradient_retention"], 3), A[1.0]["PSNR"] - A[2.0]["PSNR"], f(A[1.0]["SSIM"], 4), f(A[2.0]["SSIM"], 4), f(A[1.0]["PSNR"], 2), Bv[0.5]["PSNR"] - A[1.0]["PSNR"], Bv[2.0]["PSNR"] - A[1.0]["PSNR"])))
    kw = R["q5_2_wiener_kernel_sigma20"]
    B.append(("p", "**Why a correctly specified Wiener filter still blurs edges.** The estimator is one fixed zero-phase transfer function $W(u,v)$ applied to every pixel, i.e. a convolution with the *same* kernel everywhere; it is optimal for the *ensemble-average* mean-square error of a stationary field. A step edge is a non-stationary event: its energy is spread over all frequencies ($\\propto1/f$) and at the frequencies where $S_{ff}(f)<S_{nn}$ the filter must attenuate (the edge's high frequencies are indistinguishable, on average, from noise), so the edge is blurred whatever the local situation; averaged over all pixels this is MSE-optimal because most pixels are flat. The theory promises the minimal *average* squared error among linear filters; it says nothing about edge sharpness, local error, or perceptual quality (the error map of a Wiener result is concentrated at edges), and it assumes second-order statistics only (a Gaussian field has no edges). Measured at $\\sigma=20$: the correctly specified filter retains only %s of the mean gradient magnitude at the strongest edges; its spatial kernel (inverse DFT of $W$) has unit sum, peak %s and half-maximum width %.0f px, with negligible side lobes ($|\\min|/\\max=%s$): a mild, essentially positive low-pass, so there is no ringing but there is blur."  % (f(A[1.0]["edge_gradient_retention"], 3), f(kw["peak"], 3), kw["half_max_width_px"], g(kw["|min|/max"], 2))))

    # real photo
    rn = R["q5_2_real_noise"]
    rw = R["q5_2_real_wiener"]
    B.append(("h2", "5.2b White-noise Wiener filtering of a genuinely noisy photograph"))
    B.append(("p", "**Photographs.** Photograph B (`IMG_20261026_195556198.jpg`, 4080x3072, EXIF **ISO 6400**, 1/16.7 s, f/1.87, BrightnessValue -4.6: a dark room lit by a few windows/lights) is the real low-light photo; photograph A (`IMG_20261026_195540763.jpg`, ISO 734, 1/14 s, BrightnessValue -0.9) shows the same room much brighter and is used only for a *qualitative* comparison of noise statistics. They are *not* a registered clean/noisy pair (different exposure, illumination colour and framing), so **no PSNR, SSIM or MSE is computed between them or between either and any denoised result**. Low exposure alone does not establish sensor noise; the evidence below is a direct measurement in flat regions."))
    B.append(("p", "**Noise-power estimation (no reference needed).** (1) Flat-region estimator: the frame is divided into non-overlapping 24x24 patches (patches whose mean is outside 8-245 are discarded because of clipping); a plane is fitted by least squares and removed from each patch; the noise standard deviation of a patch is the residual standard deviation with the $(n-3)$ degrees-of-freedom correction; the flattest 10% of patches (smallest mean absolute 3x3 Laplacian) are kept and the median is reported per channel. (2) Immerkaer's Laplacian estimator on the whole frame as a cross-check. (3) A *noise-level function*: the same patch statistic versus patch mean level (green channel, flattest 25% of patches)."))
    rows = []
    for k, nm in (("A", "A (ISO 734)"), ("B", "B (ISO 6400)")):
        for ch in rn[k]["channels"]:
            rows.append([nm, ch["channel"], ch["n_flat"], f(ch["mean_level_of_flat_patches"], 1), f(ch["median_sigma_flat_patches"], 2), "%.2f-%.2f" % tuple(ch["sigma_flat_p25_p75"]), f(ch["immerkaer_whole_frame"], 2)])
    B.append(("table", "Table 5.3. Noise standard deviation (8-bit grey levels) of the original 4080x3072 photographs: flat-patch estimator per channel (median of the flattest 10% of 24x24 patches, with the inter-quartile range) and Immerkaer's whole-frame estimate.", ["photo", "channel", "flat patches", "their mean level", "sigma flat-patch (median)", "IQR", "sigma Immerkaer"], rows, "llrrrrr"))
    rows = [[("%d-%d" % tuple(r["level_range"])), f(r["sigma_A"], 2), r["nA"], f(r["sigma_B"], 2), r["nB"], f(r["ratio_B/A"], 2)] for r in rn["matched_level_ratio_B_over_A"]]
    B.append(("table", "Table 5.4. Noise-level function (green channel): median detrended patch std in bins of patch mean level (flattest 25% of patches) for A and B and their ratio. Noise grows with signal level in both images (signal-dependent, shot-noise-like) and the ratio at matched level is the like-for-like comparison. The brightest bin of B contains only 70 patches (light sources, clipped/JPEG-processed) and is not reliable.", ["level range", "sigma A", "patches A", "sigma B", "patches B", "ratio B/A"], rows, "rrrrrr"))
    rr = rn["matched_level_ratio_B_over_A"]
    B.append(("p", "**Findings.** Photograph B has a flat-patch noise standard deviation of about %.1f-%.1f grey levels (R/G/B medians %s) against %.2f-%.2f for A. At matched signal levels the ratio B/A is %.1f, %.1f, %.1f, %.1f (in the four reliable level bins), i.e. roughly **3.3-4x** - noticeably more than the ratio 2.8 of the Immerkaer whole-frame estimates. The discrepancy between estimators is not random: the Immerkaer operator is a high-pass Laplacian and under-estimates noise that is spatially correlated (see below), while the flat-patch statistic includes all frequencies. The ISO ratio is 6400/734 = 8.7; shot-noise-limited sensors scale noise with $\\sqrt{\\text{gain}}=2.95$ and read-noise-limited ones with the gain, so 3.3-4 is physically plausible, but the in-camera processing (denoising, multi-frame stacking, JPEG) is unknown, so no sensor-level claim is made. In absolute terms the noise of B is small (about 1%% of full scale, 2.5-3 grey levels), smaller than the weakest synthetic case ($\\sigma=5$) of Section 5.1."  % (min(c["median_sigma_flat_patches"] for c in rn["B"]["channels"]), max(c["median_sigma_flat_patches"] for c in rn["B"]["channels"]), "/".join(f(c["median_sigma_flat_patches"], 2) for c in rn["B"]["channels"]), min(c["median_sigma_flat_patches"] for c in rn["A"]["channels"]), max(c["median_sigma_flat_patches"] for c in rn["A"]["channels"]), rr[0]["ratio_B/A"], rr[1]["ratio_B/A"], rr[2]["ratio_B/A"], rr[3]["ratio_B/A"])))
    B.append(("fig", "figures/q5_real_noise_analysis.png", "Left: detrended patch standard deviation vs patch mean level for A and B (green channel; flattest 25% of patches). Right: radially averaged noise power spectrum of flat 32x32 patches (8 bands up to 0.5 cycles/pixel, normalised to the mean; white noise = 1).", 1.0))
    wa, wb = rw["A"], rw["B"]
    B.append(("p", "**Application of the white-noise Wiener filter.** A 1024x1024 native-resolution crop (rows 700-1723, cols 1500-2523: window lights, curtain, dark wall) of each photograph was processed per channel with the Wiener filter of 5.1 using the flat-patch noise estimate of the *crop* ($\\hat\\sigma_{RGB}$ = %s for B, %s for A; the crop contains brighter regions than the frame average so the values exceed the frame-wide medians). Figure 5.5 shows the crop, a zoom before/after and the residual (noisy minus denoised, amplified x4)." % (", ".join(f(x, 2) for x in wb["sigma_flat_patch_RGB"]), ", ".join(f(x, 2) for x in wa["sigma_flat_patch_RGB"]))))
    B.append(("fig", "figures/q5_real_photos.png", "Real photographs at native resolution (A: top, B: bottom). Columns: 1024x1024 crop, noisy zoom, white-noise Wiener output, residual (x4 gain). The residual of B shows edge structure (window frame, arcs): the filter removes signal energy along with noise; the grain that remains in B is blotchy (low-frequency).", 1.0))
    B.append(("p", "**Qualitative comparison with the synthetic cases and departures from the white-noise model.** In the synthetic cases the noise was white (flat periodogram) and the Wiener output visibly cleaned flat areas while softening edges. On photograph B the denoised crop is only slightly different from the input (mean absolute change %.2f grey levels; residual standard deviation %.2f/%.2f/%.2f in R/G/B, i.e. %.0f-%.0f%% of the estimated $\\hat\\sigma$): the grain of B is *not* white. The noise power spectrum of flat patches (Figure 5.4, right, Table 5.5) falls by a factor of %.0f between the lowest and the highest radial band (A: %.0f), versus a flat spectrum for white noise: the noise is dominated by low spatial frequencies (blotches several pixels wide), which is where the signal PSD is large and therefore where the Wiener gain is $\\approx1$ - the filter cannot remove it - while the white-noise assumption (flat $S_{nn}$ set to the *total* measured variance) over-attributes power to the high-frequency bands where the true noise power is nearly zero, so there it removes image detail rather than noise (the residual of Figure 5.5 resembles an edge map). Other violations: (i) *signal dependence*: noise grows with brightness (Table 5.4; shot noise is Poisson, $\\sigma^2\\propto$ signal), so a single $\\sigma$ per channel is too large in the shadows and too small near lights; (ii) *demosaicing*: the camera interpolates one colour sample per pixel, which correlates neighbouring pixels and the colour channels (the three channel estimates are nearly equal, which is the signature of processing that treats channels alike); (iii) *in-camera sharpening and denoising*: sharpening boosts mid/high bands and denoising smooths flat areas non-uniformly; (iv) *JPEG compression*: 8x8 block quantisation produces structured, non-Gaussian, spatially correlated errors, strongest in dark flat regions; (v) clipping near the lights. A shot-noise-aware model would use a variance-stabilising transform (Anscombe) before the Wiener filter, and a coloured-noise Wiener filter would use the measured NPS instead of a flat $S_{nn}$." % (wb["mean_abs_change"], wb["residual_std_RGB_(noisy-denoised)"][0], wb["residual_std_RGB_(noisy-denoised)"][1], wb["residual_std_RGB_(noisy-denoised)"][2], 100 * min(wb["residual_std_over_sigma_est"]), 100 * max(wb["residual_std_over_sigma_est"]), wb["NPS_low_over_high_band_ratio"], wa["NPS_low_over_high_band_ratio"])))
    rows = [["A"] + [f(x, 3) for x in wa["NPS_radial_8bands_(green,flat_patches)_normalised_to_mean"]], ["B"] + [f(x, 3) for x in wb["NPS_radial_8bands_(green,flat_patches)_normalised_to_mean"]]]
    B.append(("table", "Table 5.5. Radially averaged noise power spectrum of flat patches (green channel, %d / %d patches of 32x32, plane-detrended), 8 equal bands from 0 to 0.5 cycles/pixel, normalised to the mean over bands (white noise would give 1 in every band). Lowest band includes some residual low-frequency scene texture; the strong decay towards high frequency is the evidence of spatially correlated noise." % (wa["n_flat_patches_used"], wb["n_flat_patches_used"]), ["photo"] + ["band %d" % i for i in range(1, 9)], rows, "lrrrrrrrr"))
    return B
